entries[184562] = { ["name"] = "Gelassenheitsstein", ["text"] = "Wird beim Aufheben gebunden\n\"Gewöhnliche Kieselsteine dienen vielen Aspiranten als Fokuspunkt für ihre Meditation und werden nicht selten zu schlichten Schmuckstücken verarbeitet.\"\nVerkaufspreis:" }
entries[184563] = { ["name"] = "Animakondensator", ["text"] = "Wird beim Aufheben gebunden\n\"Niemand außer den Sammlern weiß, wie man dieses Gerät benutzt, obwohl es das Geheimnis hinter der Macht der Zenturionenarmee der Bastion birgt.\"\nVerkaufspreis:" }
entries[184564] = { ["name"] = "Kyrianische Spieluhr", ["text"] = "Wird beim Aufheben gebunden\n\"Winzige Glocken werden von klitzekleinen Glockenspielen zum Läuten gebracht, die sich um eine räumliche Darstellung der Bastion drehen.\"\nVerkaufspreis:" }
entries[184565] = { ["name"] = "Kyrianischer Wellensimulator", ["text"] = "Wird beim Aufheben gebunden\n\"Resonanzkammern fangen das Plätschern des Wassers an der Küste ein und projizieren es weiter.\"\nVerkaufspreis:" }
entries[184566] = { ["name"] = "Adrimas Potpourri", ["text"] = "Wird beim Aufheben gebunden\n\"Der staubige Geruch getrockneter Blumen von den Feldern der Bastion steigert die Achtsamkeit.\"\nVerkaufspreis:" }
entries[184567] = { ["name"] = "Handgestrickter Provostenpullover", ["text"] = "Wird beim Aufheben gebunden\n\"Manchen Aspiranten fällt das Meditieren leichter, wenn ihre Hände dabei etwas zu tun haben. Zum Glück liegen immer genügend Wolkenwandererhaare herum.\"\nVerkaufspreis:" }
entries[184568] = { ["name"] = "Kurzklinge des sündigen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n32 - 54 Schaden Geschwindigkeit 2.60\n(16.5 Schaden pro Sekunde)\n+15 Beweglichkeit\n+22 Ausdauer\nErhöht Eure Tempowertung um + 9.\n+ 20 Vielseitigkeit\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
