entries[184588] = { ["name"] = "Seelenstabilisierender Talisman", ["text"] = "Dauerhafte Aufwertung: Der Schlund\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Legt den seelenstabilisierenden Talisman an, was Euch permanent immun gegen ' Seelenmal ' der schlundgebundenen Entführer macht.\nVe'nari muss Euch gegenüber zwiespältig oder positiver eingestellt sein.\n\"Ein verzauberter Talisman, der die Seele des Trägers vor den dunkelsten Kräften der Schlundgebundenen schützen soll.\"" }
