entries[184605] = { ["name"] = "Zeichen des Ungesehenen", ["text"] = "Dauerhafte Aufwertung: Der Schlund\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Prägt das Zeichen auf Euren Körper, wodurch Ihr permanent immun gegen ' Mal des Kerkermeisters ' der schlundgebundenen Assassinen werdet.\nVe'nari muss Euch gegenüber unverbindlich oder positiver eingestellt sein.\n\"Ein mächtiges Zeichen, überzogen mit andersweltlicher Tinte, das den Schlundgebundenen abgenommen wurde.\"" }
entries[184606] = { ["name"] = "Enger vernähen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Konstrukt ist 30% kleiner. Engere Nähte platzen, wenn jemand auf dem Konstrukt reitet. (10 Sek. Abklingzeit)\n\"Kleiner und immer noch genauso hässlich.\"\nVerkaufspreis:" }
