entries[184613] = { ["name"] = "Eingeschlossene Risswandereressenz", ["text"] = "Dauerhafte Aufwertung: Der Schlund\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht die Nutzung von chaotischen Risssteinen, die im Schlund zu finden sind, zu Transportzwecken.\nVe'nari muss Euch gegenüber besorgt oder positiver eingestellt sein.\n\"Ein Teil einer schlundgebundenen Seele, eingeschlossen in einem gläsernen Stein. Sie bringt chaotische Risssteine dazu, dem Träger Zugriff zu erlauben.\"" }
entries[184614] = { ["name"] = "Essenz des Elends", ["text"] = "Questgegenstand" }
entries[184615] = { ["name"] = "Außerdimensionale Taschen", ["text"] = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt in Torghast zusätzlichen Lagerplatz, sodass mehr Obleronausrüstung gefunden werden kann.\nVe'nari muss Euch gegenüber besorgt oder positiver eingestellt sein.\n\"Der Innenraum dieser Taschen ist viel größer als ihr äußeres Erscheinungsbild.\"" }
entries[184617] = { ["name"] = "Reif des Vorrangs", ["text"] = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: In Torghast besteht eine Chance, dass Mittlerhändler Euch ungewöhnliche Optionen anbieten.\nVe'nari muss Euch gegenüber unverbindlich oder positiver eingestellt sein.\n\"Dieser Reif verdeutlichte einst den Status Ve'naris im Kartell Ve. Nun gehört er Euch.\"" }
entries[184618] = { ["name"] = "Rangabzeichen: Akquisiteur", ["text"] = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: In Torghast besteht eine Chance, dass Mittlerhändler Euch eine seltene Option anbieten.\nVe'nari muss Euch gegenüber herzlich oder positiver eingestellt sein.\n\"Dies weist Euch als ein Stellvertreter des Kartells Ve aus. Dies seid Ihr definitiv nicht, aber das wissen sie ja nicht.\"" }
entries[184619] = { ["name"] = "Lupe des bezaubernden Charmes", ["text"] = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: In Torghast bietet Euch ein Mittlerhändler gelegentlich Animaschätze zu vergünstigten Preisen an.\nVe'nari muss Euch gegenüber herzlich oder positiver eingestellt sein.\n\"Ve'nari hat diese Juwelierslupe mit einem Anziehungszauber versehen, der manche Mittler dazu bewegt, Euch Sonderangebote zu unterbreiten.\"" }
entries[184620] = { ["name"] = "Gefäß der unglückseligen Geister", ["text"] = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Euer erster Tod in Torghast zählt nicht.\nVe'nari muss Euch gegenüber besorgt oder positiver eingestellt sein.\n\"Gefährliche Magie verknüpft das Schicksal desjenigen, der dieses Gefäß ergreift, mit demjenigen des Geistes, der darin wohnt.\"" }
entries[184621] = { ["name"] = "Ritualprisma der Wahrsagung", ["text"] = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: In Torghast ist Eure Chance, epische Animaboni zu erhalten, dauerhaft erhöht.\nVe'nari muss Euch gegenüber zwiespältig oder positiver eingestellt sein.\n\"Ve'nari hat in diesen Kristall Glyphen eingraviert, die angeblich gegen die Launen des Schicksals schützen.\"" }
entries[184622] = { ["name"] = "Stygischer Hammer", ["text"] = "Questgegenstand\nBenutzen: Zerstört die anvisierte gepanzerte Hülle. (5 Sek. Abklingzeit)" }
entries[184624] = { ["name"] = "Extrazuckriges Fischfestmahl", ["text"] = "Benutzen: Richtet für Eure Gruppe ein großartiges Festmahl her!\n\nStellt im Verlauf von 20 Sek. 173077 Gesundheit und 138461 Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt, was Eure Vielseitigkeit für 20 Min. erhöht.\nVerkaufspreis:" }
entries[184625] = { ["name"] = "Rezept: Extrazuckriges Fischfestmahl", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein extrazuckriges Fischfestmahl zubereitet.\nBenötigt Klassische Kochkunst (150)\nVerkaufspreis:\nExtrazuckriges Fischfestmahl\nBenutzen: Richtet für Eure Gruppe ein großartiges Festmahl her!\n\nStellt im Verlauf von 20 Sek. 173077 Gesundheit und 138461 Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt, was Eure Vielseitigkeit für 20 Min. erhöht.\nVerkaufspreis:\nBenötigt Dunkelmond-Dolchmaul (5)" }
