entries[184649] = { ["name"] = "Schlundrattenkanone", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verschießt eine explodierende Schlundratte auf Euer Ziel und fügt allen Gegnern innerhalb von 8 Metern (Gesamtgesundheit / 10) Schattenflammenschaden zu. Die Schlundratte wird dabei getötet. Kann nur in Torghast eingesetzt werden. (5 Min Abklingzeit)\n\"Eine extrem großkalibrige Waffe. Es handelt sich um eine Spezialanfertigung, um die Ratten, die Torghast ihr Heim nennen, mit hoher Geschwindigkeit in andere Kreaturen zu feuern.\"\nVerkaufspreis:" }
entries[184650] = { ["name"] = "Abenteuerkampagnenfortschritt", ["text"] = "\"Diese Herausforderung führt zu weiteren Abenteuern mit größeren Belohnungen.\"" }
entries[184651] = { ["name"] = "Schlundberührtes Miasma", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Umgibt Euch 30 Min. lang mit widerlichem Miasma, das Schlundratten innerhalb von 15 Metern alle 1 Sek. (Gesamtgesundheit / 5) Schaden zufügt. Kann nur in Torghast verwendet werden. (5 Min Abklingzeit)\nVe'nari muss Euch gegenüber unverbindlich oder positiver eingestellt sein.\n\"Ein ekelhaftes Gas in einer Phiole. Diese Substanz ist besonders wirksam gegen die allgegenwärtigen Schlundratten.\"\nVerkaufspreis:" }
entries[184652] = { ["name"] = "Phantasmatischer Infusor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verbraucht 100 Phantasma und nutzt die Energie der Substanz, um Euch für 30 Min. zu ermächtigen. Kann nur in Torghast verwendet werden. (15 Min Abklingzeit)\nVe'nari muss Euch gegenüber zwiespältig oder positiver eingestellt sein.\n\"Es heißt, dieses Gerät verbraucht Phantasma, um Euch für begrenzte Zeit mit großer Macht zu erfüllen. Das Gerät ist wiederverwendbar, das Phantasma wird durch den Prozess allerdings verbraucht.\"\nVerkaufspreis:" }
entries[184653] = { ["name"] = "Belebte Levitationskette", ["text"] = "Dauerhafte Aufwertung: Der Schlund\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Unterwerft das Kettenstück Eurem Willen, sodass Ihr es an bestimmte Orte in der Nähe leiten könnt.\nVe'nari muss Euch gegenüber unverbindlich oder positiver eingestellt sein.\n\"Dieses Glied einer magischen Kette wurde von einem hilflosen Gefangenen des Kerkermeisters im Schlund geborgen. Es enthält immer noch eine gewisse Macht.\"" }
entries[184654] = { ["name"] = "Vergessener Schemenschal", ["text"] = "Wird beim Aufheben gebunden\nBrust Stoff\n20 Rüstung\n+23 Intelligenz\n+34 Ausdauer\nErhöht Eure Tempowertung um + 25.\nErhöht Eure Meisterschaftswertung um + 20.\nHaltbarkeit 165 / 165\nVerkaufspreis:" }
