entries[184839] = { ["name"] = "Versagende Zenturiosteuerung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 20.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Eure Hauptwert für 15 Sek. um 38 zu erhöhen.\nVerkaufspreis:" }
entries[184840] = { ["name"] = "Gesangbuch des Pfades", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 20 Vielseitigkeit\nAnlegen: Eure Schadensfähigkeiten haben eine Chance, Eurem Ziel 600 Heiligschaden zuzufügen, wenn Ihr bei mehr als 50% Gesundheit seid, oder Euch um 926 Gesundheit zu heilen, während Ihr bei weniger als 50% Gesundheit seid.\nVerkaufspreis:" }
entries[184841] = { ["name"] = "Lyra der Heiligen Aufgaben", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+14 Intelligenz\nBenutzen: Verleiht einem Verbündeten 50 Geschwindigkeit und heilt ihn im Verlauf von 15 Sek. um [Quellwert] Gesundheit. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[184842] = { ["name"] = "Heilige Glocke des Ausbilders", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+14 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Gewährt Euch 15 Sek. lang 97 Meisterschaft. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[184843] = { ["name"] = "Geborgene Vorräte", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält von den Flickmeistern gesammelte Reagenzien.\"\n<Zum Öffnen rechtsklicken>" }
entries[184845] = { ["name"] = "Blutbefleckte Brille", ["text"] = "Wird beim Aufheben gebunden\nVerkaufspreis:" }
entries[184863] = { ["name"] = "9.1 Monster - Hand_1H_BrokerAssassin_C_01 - Red", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Faustwaffe\n1 Schaden Geschwindigkeit 2.00\n(0.5 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[184866] = { ["name"] = "Grummelbeutel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet den Beutel.\n\"Anthea hat in diesem Beutel ein paar Dinge für ihren Begleiter aufbewahrt.\"" }
entries[184867] = { ["name"] = "Plappergei", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[184868] = { ["name"] = "Schatzkiste von Nathria", ["text"] = "Heroisch\nWird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"\n<Zum Öffnen rechtsklicken>" }
entries[184869] = { ["name"] = "Schatzkiste von Nathria", ["text"] = "Wird beim Aufheben gebunden\n\"Gewährt ein Ausrüstungsteil für Eure Beutespezialisierung.\"\n<Zum Öffnen rechtsklicken>" }
entries[184870] = { ["name"] = "Stygiatensor", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Entzieht einem Stygianexus im Schlund die Stygia.\nSpürt stygiaerfüllte Bereiche im Schlund auf und markiert sie auf der Minikarte, solange der Stygiatensor in Eurem Inventar verbleibt." }
entries[184876] = { ["name"] = "Kohäsionskristall", ["text"] = "Questgegenstand\nBenutzen: Eine nekrotische Kohäsion, die Seelen mit Knochen verbindet, um einen vollständigen Körper zu erschaffen. (5 Sek. Abklingzeit)\n\"Quell einer nekrotischen Kohäsion, die Elemente von Knochen und Seelen verbindet.\"" }
entries[184894] = { ["name"] = "Thurgadens Entwürfe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[184895] = { ["name"] = "Geschmiedeter Ranseur", ["text"] = "Questgegenstand\n\"Eine ausgesprochen hochwertige Waffe, die allerdings noch mit Macht erfüllt werden muss.\"" }
entries[184901] = { ["name"] = "Mittlerdurchquerungsverstärker", ["text"] = "Dauerhafte Aufwertung: Torghast\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht Euch, verborgene Teleportationspunkte in Torghast zu sehen und zu verwenden.\nVe'nari muss Euch gegenüber besorgt oder positiver eingestellt sein.\n\"Nach zahlreichen Unglücken auf den gefährlichen Plattformen der Kaltherzinterstitia und Mort'regars wurden Teleportationsgeräte mit kurzer Reichweite erschaffen, um den dort gefangenen Mittlern sicherere Fortbewegung zu ermöglichen. Mit diesem Gerät könnt Ihr sie sehen.\"" }
entries[184915] = { ["name"] = "Barren der Dunkelschmiede", ["text"] = "Questgegenstand\n\"Mit großer Sorgfalt von dem besten Schmied der Schattenschmiede gefertigt.\"" }
entries[184916] = { ["name"] = "Siedender Flammenkern", ["text"] = "Questgegenstand\n\"Was alles andere verbrennt, ist für Dunkeleisenzwerge angenehm warm.\"" }
entries[184917] = { ["name"] = "Flammenspitzgraveur", ["text"] = "Questgegenstand\n\"Thurgadens bevorzugtes Werkzeug, um seine Kreationen mit traditionellen Runen zu verzieren.\"" }
entries[184922] = { ["name"] = "Arsenal: Lavaschmiedewaffen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen der Dunkeleisenwaffen." }
