entries[185682] = { ["name"] = "Temels Ei", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n\"Beschreibungen schrecklicher Sünden wurden in die Schale geätzt. Bringt es Temel. ( +Bonuszeit )\"\nVerkaufspreis:" }
