entries[185684] = { ["name"] = "Lord Garridans Ei", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n\"Jede Linie ist präzise aufgemalt, ohne einen einzigen Fleck an der falschen Stelle. Bringt es Lord Garridan.\"\nVerkaufspreis:" }
entries[185685] = { ["name"] = "Mechanoidbolzen", ["text"] = "Questgegenstand" }
entries[185716] = { ["name"] = "Beschädigte Aufzeichnung", ["text"] = "Questgegenstand\n\"Anima pulsiert schwach aus diesem Gerät. In den Rissen lassen sich seltsame Symbole erkennen.\"\nVerkaufspreis:" }
entries[185717] = { ["name"] = "Schlummernder Geist", ["text"] = "Konservatorium der Königin\nWird beim Aufheben gebunden\n\"Ein Geist, der im Konservatorium der Königin gepflegt werden kann.\"" }
entries[185719] = { ["name"] = "Animaerfüllte Knochen", ["text"] = "Questgegenstand\n\"Diese Knochen pulsieren vor Anima und sind unglaublich hart.\"" }
entries[185720] = { ["name"] = "Drakas Schlachthorn", ["text"] = "Questgegenstand\nBenutzen: Ruft die Maldraxxitruppen zur Unterstützung im Kampf herbei. (15 Sek. Abklingzeit)\n\"Ein Kriegshorn aus Knochen. Die Steinfassungen sind mit Runen verziert.\"" }
entries[185727] = { ["name"] = "Drakas Schlachthorn", ["text"] = "Questgegenstand\nBenutzen: Gibt den Truppen das Signal zum Vorrücken. (15 Sek. Abklingzeit)\n\"Ein Kriegshorn aus Knochen. Die Steinfassungen sind mit Runen verziert.\"" }
entries[185729] = { ["name"] = "Animageladene Rune", ["text"] = "Questgegenstand" }
entries[185732] = { ["name"] = "Archivtafel", ["text"] = "Questgegenstand\n\"Vollständig mit einer unleserlichen Schrift bedeckt.\"" }
entries[185733] = { ["name"] = "Animapartikel", ["text"] = "Questgegenstand\n\"Destillierte Anima mit genug Energie, einen Zenturio anzutreiben.\"" }
entries[185734] = { ["name"] = "Kugel der Offenbarung", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Versucht, Schreckenslords in dem Gebiet zu enthüllen." }
entries[185735] = { ["name"] = "Spitze des Leitstabs", ["text"] = "Questgegenstand\n\"Die Spitze eines rätselhaften Stabs. Archivarin Roh-Senara hat wiederholt daran erinnert, dass sie von den Schlundgebundenen ferngehalten werden muss.\"" }
entries[185736] = { ["name"] = "Glänzende goldene Feder", ["text"] = "Questgegenstand\nEinzigartig\n60 ( 60)\n\"Das helle goldene Licht dieser Feder verblasst allmählich. Sie wurde erst kürzlich verloren, und vielleicht ist ihr Eigentümer noch in der Nähe.\"" }
entries[185737] = { ["name"] = "Kleine Kettenglieder", ["text"] = "Verkaufspreis:" }
entries[185738] = { ["name"] = "Helgeschmiedetes Siegel", ["text"] = "Questgegenstand\nEinzigartig" }
entries[185739] = { ["name"] = "Kristalliner Splitter", ["text"] = "Verkaufspreis:" }
entries[185740] = { ["name"] = "Kopf von Azodius", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n60 ( 60)\n\"Der immer noch warme Kopf des Nathrezim Azodius. Hochlord Bolvar sollte über diese Bedrohung informiert werden.\"" }
entries[185741] = { ["name"] = "Auffüllung und Reparatur: Tipps und Tricks für eine Feier ohne Ende", ["text"] = "Wird an Kriegsmeute gebunden\nErfordert einen ehrfürchtigen Ruf beim Gluthof.\n\"Lehrt Euren Gräberbutler, sich für Euch um die lästigeren Aspekte der Planung eines Fests zu kümmern, sodass Ihr nach einem Gluthof nichts mehr selbst auffüllen oder reparieren müsst.\"" }
entries[185742] = { ["name"] = "Ketten der Schlundgebundenen", ["text"] = "Questgegenstand\nBenutzen: Kettet einen helgebundenen Seelenbrecher an und zerrt ihn an Euren Standort. (5 Sek. Abklingzeit)" }
entries[185743] = { ["name"] = "Ausgerissene Seite", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Herausgerissene Seite aus dem Notizbuch des Schicksalsschreibers.\"" }
entries[185746] = { ["name"] = "Gestohlener Kryptograf", ["text"] = "Questgegenstand\n\"Teil eines komplexen Schlosssystems, durch das man in ein Archiv gelangt.\"" }
entries[185749] = { ["name"] = "Geplünderte Anima", ["text"] = "Questgegenstand\n\"Spuren von Anima, die aus Korthia und von anderswo gestohlen wurde. Könnte man sinnvoller nutzen.\"" }
entries[185750] = { ["name"] = "Schreinopfergabe", ["text"] = "Questgegenstand\n\"Eine greifbare Bitte um Führung.\"" }
entries[185751] = { ["name"] = "Emblem der Schlundgebundenen", ["text"] = "Questgegenstand\n\"Der Beweis für den Niedergang eines getreuen Dieners von Zovaal dem Kerkermeister.\"" }
entries[185752] = { ["name"] = "Schlachtpläne der Schlundgebundenen", ["text"] = "Questgegenstand\n\"Ein dicker Haufen Papiere mit detaillierten Plänen der Schlundgebundenen bezüglich Korthia.\"" }
entries[185753] = { ["name"] = "Zauberfoliant der Schlundgebundenen", ["text"] = "Questgegenstand\n\"Ein Foliant mit Zaubern und Ritualen, bei denen Todesmagie zum Einsatz kommt.\"" }
entries[185754] = { ["name"] = "Verschlungene Anima", ["text"] = "Questgegenstand\n\"Aus dem Leichnam eines Verschlingers extrahierte Anima.\"" }
entries[185756] = { ["name"] = "Verformtes Phantasma", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Etwas ist daran merkwürdig. Ve'nari wird sich dafür interessieren.\"" }
entries[185757] = { ["name"] = "Erforschung der Jenseitsnavigation", ["text"] = "Questgegenstand\n\"Positionsdaten für einige der verschiedenen Leben nach dem Tode, die die Schattenlande in ihrer Gesamtheit ausmachen. Die Diagramme und Berechnungen sind dicht auf der Schriftrolle gedrängt und unverständlich.\"" }
entries[185758] = { ["name"] = "Beobachtungsdaten", ["text"] = "Questgegenstand\n\"Ein Datenpaket aus dem Überwachungsgerät eines Mittlers.\"" }
entries[185759] = { ["name"] = "Schaft des Leitstabs", ["text"] = "Questgegenstand\n\"Der Schaft eines rätselhaften Stabs. Archivarin Roh-Senara hat wiederholt daran erinnert, dass er von den Schlundgebundenen ferngehalten werden muss.\"" }
entries[185760] = { ["name"] = "Griff des Leitstabs", ["text"] = "Questgegenstand\n\"Der Griff eines rätselhaften Stabs. Archivarin Roh-Senara hat wiederholt daran erinnert, dass er von den Schlundgebundenen ferngehalten werden muss.\"" }
entries[185761] = { ["name"] = "Ein zerknitterter subversiver Handzettel", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieser Handzettel schürt Zweifel daran, dass Sin'dane wirklich fähig ist, das Haus der Rituale zu führen.\"" }
entries[185762] = { ["name"] = "Die Ungesehenen Gäste unter uns", ["text"] = "Questgegenstand\n<Zum Lesen rechtsklicken>" }
entries[185763] = { ["name"] = "Versiegelter Behälter", ["text"] = "Questgegenstand\n\"Erstaunlich leicht, enthält aber wertvolle korthianische Relikte.\"" }
entries[185764] = { ["name"] = "Foliant des Stadtportals", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort.\n100 Aufladungen" }
entries[185765] = { ["name"] = "Lieferung schwerer Hornbälge", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 10 schwere Hornbälge.\"\n<Zum Öffnen rechtsklicken>" }
entries[185766] = { ["name"] = "Fokussierkristall aus Nekrolit", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Ein kleiner summender Kristall.\"" }
entries[185767] = { ["name"] = "Ein gefaltetes Sendschreiben", ["text"] = "Questgegenstand\nEinzigartig\n\"Laut diesem Schreiben wird Kel'Thuzad seine Anhänger bald versammeln. Es ist auch von einem \"Treffen unter den Stielen\" die Rede.\"" }
entries[185768] = { ["name"] = "Eine halb verbrannte Schriftrolle", ["text"] = "Questgegenstand\nEinzigartig\n\"Im Rest wird ein Treffen von Gleichgesinnten im Süden und ein Versprechen auf baldige Macht erwähnt.\"" }
entries[185769] = { ["name"] = "Eine zerfledderte Notiz", ["text"] = "Questgegenstand\nEinzigartig\n\"Ihr könnt lediglich entziffern: \"Die Zeit naht. Haltet Euch bereit!\"\"" }
entries[185770] = { ["name"] = "Halber zersetzter Brief", ["text"] = "Questgegenstand\nEinzigartig\n\"In diesem Brief erhält der Empfänger den Auftrag, bestimmte Ritualobjekte für Kel'Thuzad zu stehlen und Chaos zu verbreiten.\"" }
entries[185771] = { ["name"] = "Utensil des Schicksalsschreibers", ["text"] = "Questgegenstand\nEinzigartig\n\"Dieses Objekt ist ein mächtiger Fokus, mit dem der Schicksalsschreiber heilige Rituale vollzieht.\"" }
entries[185772] = { ["name"] = "Dra'gora", ["text"] = "Questgegenstand" }
entries[185773] = { ["name"] = "Gunstbeweis von Baron Kel'Thuzad", ["text"] = "Questgegenstand\n\"Ein kleines Abzeichen, das die Loyalität des Trägers zu Kel'Thuzad beweist.\"" }
entries[185774] = { ["name"] = "PH Green Head Candle", ["text"] = "Kosmetisch\nWird beim Anlegen gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[185775] = { ["name"] = "Kodex des erneuerten Elans", ["text"] = "Questgegenstand\nBenutzen: Sprecht die Worte des Kodex aus, um verbündete Streitkräfte zu stärken. (3 Sek. Abklingzeit)\n\"Die Worte sind unleserlich, aber seine Macht spricht für sich selbst.\"" }
