entries[185996] = { ["name"] = "Fledderschwingensattel des Ernters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Fledderschwingen der Ernter haben keine Angst vor den Schlundgebundenen und versenken ihre Fangzähne mit Freuden in allem, was Sündensturz bedroht.\"\nBeute von:\nKriegskasse des Ernters\nZone:\nDer Schlund" }
entries[186000] = { ["name"] = "Kriegsharnisch des Beinspalters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nachdem die Rehreiter in die ausgedünnten Reihen der Wilden Jagd aufgenommen wurden, bemerkten sie schnell, dass die kräftigen Kiefer der Gorm ideal dazu geeignet sind, dichte feindliche Reihen niederzumähen.\"\nBeute von:\nKriegskasse der Wilden Jagd\nZone:\nDer Schlund" }
