entries[186014] = { ["name"] = "Bollwerk der göttlichen Absicht", ["text"] = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n\"Dieser nicht greifbare, abstrakte Schild ist aus dem Konzept der Selbstlosigkeit geschmiedet.\"" }
entries[186017] = { ["name"] = "Korthitkristall", ["text"] = "Handwerksmaterial\n\"Ein Handwerksmaterial für die Herstellung von mächtigeren Runenschnitzgegenständen. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
