entries[186043] = { ["name"] = "Portalmanipulator von Torghast", ["text"] = "Torghast, Turm der Verdammten\nEinzigartig\nBenutzen: Ändert die Portale in Torghast, sodass Ihr und Eure Gruppe in bisher unentdeckte Bereiche vorstoßen könnt.\n\"Zum Aktivieren des Schlüssels wird die gesamte Gruppe benötigt.\"" }
entries[186089] = { ["name"] = "Niyas Stab", ["text"] = "Questgegenstand\nBenutzen: Befiehlt Eurem Gormling, die anvisierte Leiche sowie alle anderen Leichen in der Nähe zu fressen, damit er wächst. (10 Sek. Abklingzeit)" }
entries[186090] = { ["name"] = "Einfache Brille", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[186091] = { ["name"] = "Onyxblendschutz", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[186092] = { ["name"] = "Historische Perspektivenwandler", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Verstärken garantiert die Sicht, dass heute alles schlimmer ist als je zuvor.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[186093] = { ["name"] = "Verdunkelte Brille", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[186094] = { ["name"] = "Entziehungsgerät", ["text"] = "Questgegenstand\nBenutzen: Fängt entzogene Wut von wütenden Schemen ein. (10 Sek. Abklingzeit)\n\"Nützlich, um wütenden Schemen die Wut zu entziehen.\"" }
entries[186095] = { ["name"] = "Gromitzähne", ["text"] = "Questgegenstand\n\"Die großen, spitzen Zähne eines Gromits. Sie sind deutlich größer, als zu erwarten war.\"" }
entries[186097] = { ["name"] = "Heirmirs Runenklinge", ["text"] = "Questgegenstand\nBenutzen: Lädt die Runenklinge mit der Anima bereitwilliger Seelen in der Nähe. (5 Sek. Abklingzeit)\n\"Wird von Seelen angetrieben, ob bereitwillig oder nicht.\"" }
entries[186099] = { ["name"] = "Apparat für räumliche Neuausrichtung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fügt einem Gegenstand der Saison 1 von Shadowlands, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Halsketten, Armschienen, Gürtel und Ringe angewandt werden.\n\"Dieses Gerät lässt in Eurer Ausrüstung einen räumlichen Miniaturriss entstehen, in den ein Edelstein genau passt.\"" }
entries[186101] = { ["name"] = "Schlüssel des Verhörers", ["text"] = "Questgegenstand\n\"Für jedes Schloss gibt es einen Schlüssel. Dieser Schlüssel ist für den Käfig, in dem Archivarin Roh-Senara gefangen ist.\"" }
entries[186102] = { ["name"] = "Lady Mondbeeres Zauberstab", ["text"] = "Questgegenstand\nBenutzen: Verwendet den Zauberstab, um den anvisierten Gegner zu schrumpfen oder die anvisierte Schlundratte zu vergrößern. (10 Sek. Abklingzeit)" }
entries[186103] = { ["name"] = "Geschirr des unvergänglichen Schattenhunds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Teile des unvergänglichen Schattenhunds haben schon viele Schlachtfelder geziert, doch dieser jüngste Kampf war womöglich das erste Mal, dass sie alle zusammen gekämpft haben.\"\nBeute von:\nKriegskasse der Unvergänglichen Armee\nZone:\nDer Schlund" }
entries[186105] = { ["name"] = "Klingenschwingenkrallen", ["text"] = "Questgegenstand\n\"Die kraftvollen Krallen der Klingenschwingen können selbst die stärksten Rüstungen durchdringen.\"" }
